pragma solidity ^0.8.10;

/// @title IVenaPythPrices
/// @notice Interface for the VenaPythPrices contract
interface IVenaPythPrices {
    /// @notice Represents a price update at a specific timestamp
    /// @dev Struct not completely packed as the sizes match what is returned
    /// from Pyth
    struct FeedPrice {
        uint64 timestamp;
        uint64 price;
        int16 exponent;
        uint64 confidence;
    }
    /// @notice Gets the latest price for a given feed ID
    /// @param feedId The feed identifier
    /// @return price The latest price for the feed
    function getLatestPrice(uint32 feedId) external view returns (uint64);

    /// @notice Gets the latest timestamp for a given feed ID
    /// @param feedId The feed identifier
    /// @return timestamp The timestamp of the latest price update
    function getLatestTimestamp(uint32 feedId) external view returns (uint64);

    /// @notice Gets the latest price and timestamp for a given feed ID
    /// @param feedId The feed identifier
    /// @return price The latest price for the feed
    /// @return timestamp The timestamp of the latest price update
    function getLatestPriceAndTimestamp(uint32 feedId) external view returns (uint64 price, uint64 timestamp);

    /// @notice Gets the number of price updates for a given feed ID
    /// @param feedId The feed identifier
    /// @return count The number of price updates stored
    function getPriceHistoryLength(uint32 feedId) external view returns (uint256);

    /// @notice Gets a specific price entry by index
    /// @param feedId The feed identifier
    /// @param index The index in the price history array (0-indexed)
    /// @return feedPrice The price entry at the specified index
    function getPriceAtRound(uint32 feedId, uint256 index) external view returns (FeedPrice memory);
}
